import 'package:flutter/material.dart';
import 'package:lottie/lottie.dart';

class ControlledLottieExample extends StatefulWidget {
  const ControlledLottieExample({super.key});

  @override
  State<ControlledLottieExample> createState() => _ControlledLottieExampleState();
}

class _ControlledLottieExampleState extends State<ControlledLottieExample>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  bool _isPlaying = false;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(vsync: this);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  void _togglePlay() {
    setState(() {
      if (_isPlaying) {
        _controller.stop();
      } else {
        _controller.repeat();
      }
      _isPlaying = !_isPlaying;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('애니메이션 제어')),
      body: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Lottie.asset(
            'assets/animations/heart.json',
            controller: _controller,
            width: 200,
            height: 200,
            onLoaded: (composition) {
              // 애니메이션 길이 설정
              _controller.duration = composition.duration;
            },
          ),
          const SizedBox(height: 20),
          // 진행률 슬라이더
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 40),
            child: AnimatedBuilder(
              animation: _controller,
              builder: (context, child) {
                return Slider(
                  value: _controller.value,
                  onChanged: (value) {
                    _controller.value = value;
                  },
                );
              },
            ),
          ),
          const SizedBox(height: 20),
          // 제어 버튼들
          Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              IconButton(
                icon: const Icon(Icons.replay),
                onPressed: () {
                  _controller.reset();
                  setState(() => _isPlaying = false);
                },
              ),
              IconButton(
                icon: Icon(_isPlaying ? Icons.pause : Icons.play_arrow),
                iconSize: 48,
                onPressed: _togglePlay,
              ),
              IconButton(
                icon: const Icon(Icons.fast_forward),
                onPressed: () {
                  _controller.forward();
                  setState(() => _isPlaying = true);
                },
              ),
            ],
          ),
          const SizedBox(height: 20),
          // 속도 조절
          Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              const Text('속도: '),
              ...[0.5, 1.0, 1.5, 2.0].map((speed) {
                return TextButton(
                  onPressed: () {
                    _controller.duration = Duration(
                      milliseconds: (1000 / speed).round(),
                    );
                  },
                  child: Text('${speed}x'),
                );
              }),
            ],
          ),
        ],
      ),
    );
  }
}

