class _TapToPlayLottie extends StatefulWidget {
  @override
  State<_TapToPlayLottie> createState() => _TapToPlayLottieState();
}

class _TapToPlayLottieState extends State<_TapToPlayLottie>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(vsync: this);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: () {
        if (_controller.isCompleted) {
          _controller.reset();
        }
        _controller.forward();
      },
      child: Lottie.asset(
        'assets/animations/like.json',
        controller: _controller,
        width: 100,
        height: 100,
        onLoaded: (composition) {
          _controller.duration = composition.duration;
        },
      ),
    );
  }
}

